Lemma uv_edenot : forall E1 x v, uv E1 x = v -> edenot E1 x = Z_to_bv 64 v.
Proof. intros E1 x v <-. unfold PB.uv. apply bv_eq. rewrite Z_to_bv_unsigned. symmetry. apply bv_wrap_small. apply bv_unsigned_in_range. Qed.
Lemma exit_gen : forall g1 M0c, OKV M0c -> forall i c k ps1 pc stv morev,
  is_leaf i c k ps1 (CC.TOther pc) -> PB.exit_base_chk GT.NF RETPC c ps1 = true -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true -> has_cur ps1 = true ->
  view_chk (SR.ps_cells ps1) (cur_of ps1) stv morev = true ->
  (forall E1 E' R' (M1 M' : mem) model1, env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XIv g1 i E1 M1 -> HAMBV g1 M0c i E1 M' model1 -> env_agree GT.NF E0 E' ->
      L5.defined M' E 16 -> (forall a, 0 <= a < hl_ceil L -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      exists (more' : bool) (code p' : Z) (g' : PML.ls_state),
        uv E' morev = PML.b2z more' /\ uv E' (cur_of ps1) = p' /\ p <= p' <= e /\
        PML.ec_at M' E code /\ (code <> 0 -> more' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\ L5.bytes_at RSEGS M' sb (PML.ps_stack ps) /\
        forall buf, let ps' := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) level (PML.ps_stack ps) sb scap bcap bptr buf (Some (p', e)) in
          PML.wf_ps ps' /\ PMX.key_inv ps' /\ PML.buf_need ps' = 0 /\ ((code = 0 /\ p < p' /\ more' = true) \/ code = 11) /\
          SPTW.w3x PMW.FParseNull cw ww M' P ps ps' ww eg g1 code) ->
  CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros g1 M0c OKV0 i c k ps1 pc stv morev IL Hchk Hbl Hhc Hview HV.
  intros fx' E1 R1 M1 m1 E' R' M' HAt [HAmb HX] HFP Hag HLF _.
  pose proof Hentry as (Hra & Hraok & _ & _ & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (kitx SPTX.okV_defc M0c OKV0) as DEFC.
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; first [apply CL5.ev_reg | exact (SPT.EV0 mw B ps R line0 pos0 XV ebf x)]).
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (gblocks_amb g1 M0c i E1 M1 m1 HAmb) as GB.
  pose proof (amb_agree g1 M0c i E1 M1 m1 HAmb) as HagE1.
  apply (PB.exit_ret L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS K (XIv g1)
           (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) (fun _ => 0) (fun _ => 0)
           SCRC (proj2 S7) S6 DEFC R EV r Hra Hraok heap_ok3 RETPC i c k ps1 pc ret_at IL Hchk fx' E1 R1 M1 m1 E' R' M' HAt HAmb Hag HLF).
  intros HRP HP HA' HagE'.
  pose proof HA' as HA'0.
  destruct HA' as (Hmo1 & Hbv1 & _ & (cr1 & HH1 & HC1) & _ & _).
  pose proof HX as (_ & _ & HGF).
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
  pose proof OBJS as ((OP1 & OP2 & _) & _ & _ & (OE1 & OE2 & _) & _).
  assert (DEFE : L5.defined M' E 16).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 E 16 HA'0 OKV0).
    - exact (proj1 (proj2 HEC)).
    - left. lia. }
  assert (DEFP : L5.defined M' P 272).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 P 272 HA'0 OKV0).
    - exact (SPT.pa_def _ _ _ HPA).
    - left. lia. }
  destruct (HV E1 E' R' M1 M' m1 Hag HLF HX HA'0 HagE' DEFE FB)
    as (more' & code & p' & g' & Hmo' & Hcur' & Hpp & HEC2 & Hcm & HLS2 & Hg' & Hstk2 & Hps).
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HK.
  pose proof (FRZ E' HagE') as (F2 & FP & FE & FV & F41 & F42 & F43 & F44 & F45 & F46 & F36 & F38 & F39 & F40 & F3839 & F3840 & FPE & FCE & F32 & F33 & F34).
  destruct (FRZW E' HagE') as (FSEG & FWLEN & FWEND & _).
  pose proof Hpe as Hpe0.
  unfold view_chk in Hview.
  destruct (SPA.pview_w (SR.ps_cells ps1) Pb PE CE) as [pv|] eqn:Hpv; [|discriminate Hview].
  repeat rewrite Bool.andb_true_iff in Hview.
  destruct Hview as (((((((((((Vl & Vwe) & Vwp) & Vst) & Vsst) & Vnst) & Vmo) & Vdo) & Vsz) & Vsb) & Vse) & Vsc).
  apply expr_eqb_eq in Vl, Vwe, Vwp, Vst, Vsst, Vnst, Vmo, Vdo, Vsz, Vsb, Vse, Vsc.
  assert (HSL : Z.of_nat (length (PML.ps_stack ps)) <= scap) by (pose proof HPA as Q; unfold PML.parser_at in Q; unfold scap; tauto).
  assert (PL : 2 ^ 32 <= P) by lia.
  assert (PH : P + 272 <= 2 ^ 63) by lia.
  assert (Hmore_v : uv E' (PB4.pv_more pv) = PML.b2z more') by (rewrite Vmo; exact Hmo').
  assert (Hdone_v : uv E' (PB4.pv_done pv) = PML.b2z (PML.ps_done ps)) by (rewrite Vdo; exact F46).
  assert (Hsb_v : L5.bytes_at RSEGS M' (uv E' (PB4.pv_sb pv)) (PML.ps_stack ps)) by (rewrite Vsb, F38; exact Hstk2).
  assert (Hse_v : uv E' (PB4.pv_send pv) = uv E' (PB4.pv_sb pv) + Z.of_nat (length (PML.ps_stack ps))).
  { rewrite Vse, Vsb, F38. change SEND0 with (APC.eadd (EVar 38) (EVar 39)). rewrite F3839. reflexivity. }
  assert (Hsc_v : uv E' (PB4.pv_scend pv) = uv E' (PB4.pv_sb pv) + scap) by (rewrite Vsc, Vsb, F38, F3840; reflexivity).
  assert (Hwp_v : edenot E' (PB4.pv_wptr pv) = Z_to_bv 64 (fst (PSA.wincells (Some (p', e))))) by (rewrite Vwp; apply uv_edenot; exact Hcur').
  assert (Hwe_v : edenot E' (PB4.pv_wend pv) = Z_to_bv 64 (snd (PSA.wincells (Some (p', e))))) by (rewrite Vwe; apply uv_edenot; exact FWEND).
  assert (Hpe_v : match Some (p', e) with Some (p0, e0) => p0 <= e0 | None => True end) by lia.
  destruct (SPA.parser_view_w E' M' (SR.ps_cells ps1) Pb PE CE pv P more' (PML.ps_done ps) (PML.ps_stack ps) scap (Some (p', e)) HK Hpv FP PL PH Hmore_v Hdone_v Hsb_v Hse_v Hsc_v HSL Hwp_v Hwe_v Hpe_v DEFP)
    as (buf & HPA2 & Hbuf & _).
  rewrite Vst, Vsst, Vnst, Vl, Vsb, F43, F44, F41, F38, FPE, FCE in HPA2.
  rewrite Vsz, F36 in Hbuf.
  destruct (Hps buf) as (HWF2 & HKI2 & Hneed2 & HRel & HW3).
  set (ps2 := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) level (PML.ps_stack ps) sb scap bcap bptr buf (Some (p', e))) in *.
  assert (Hden : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps).
  { rewrite (CH2.blocks_eqb_eq _ _ Hbl). exact (kit SPT.den_BL0 E1 HagE1). }
  destruct WINF as (ch & Hch & Hch1 & Hch2 & Hdw).
  assert (HWIN2 : PML.win_ok M' LBo ps2).
  { unfold PML.win_ok. cbn [ps2 PML.ps_win]. exists ch. split; [exact Hch|]. split; [lia|]. split; [lia|].
    assert (Dw : L5.defined M' p wlen).
    { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 p wlen HA'0 OKV0 Hdw). right. exists ch. split; [exact Hch|]. unfold wlen. lia. }
    apply (L5.defined_sub _ _ _ _ _ Dw); unfold wlen; lia. }
  assert (HBB2 : PML.buf_bound ps2 B).
  { destruct HBB as (HB1 & HB2). split; [|exact HB2]. rewrite Hneed2. pose proof need0 as N0.
    unfold PML.winlen in *. rewrite Hwin in HB1. cbn [ps2 PML.ps_win PML.ps_buf]. rewrite Hbuf. unfold size0 in *. lia. }
  pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV2 & HLIT2).
  pose proof (kitx SPTX.okV_hpres g1 M0c M' OKV0 HP) as HP2.
  assert (HSY : code = 0 -> PMX.enc_sync ps2 g1) by (intros _; exact (sync_exit g1 i ps2 HGF eq_refl HKI2)).
  apply (Hcont fx' R' M' m1 (PML.ps_blocks ps2 ++ LBo ++ gB g1) cr1 LBo W HFP); [| exact HRP | exact HP2 | exact Hbv1 | unfold CH2.cur, CH2V.LBr in HH1; rewrite Hden in HH1; exact HH1].
  exists ps2, code, g', g1.
  split; [exact HPA2|]. split; [exact HWF2|]. split; [exact HWIN2|]. split; [exact HBB2|]. split; [exact HEC2|].
  split; [exact Hcm|]. split; [exact HLS2|]. split; [exact Hg'|]. split; [exact HINV2|]. split; [exact HLIT2|].
  split; [exact HSY|]. split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
  split; [exact HC1|].
  split; [|exact HW3].
  unfold PMS.literal_rel. destruct HRel as [(H0 & Hlt & Hm) | H11]; [left | right; exact H11].
  unfold PMS.consumed. cbn [ps2 PML.ps_win PML.ps_more PML.ps_stack PML.ps_level]. rewrite Hwin.
  split; [exact H0|]. split; [split; [reflexivity | lia]|]. split; [exact Hm|]. split; reflexivity.
Qed.

