Lemma wmatch_vis : forall c k ps1 E' R' (M1 M' : mem), is_leaf 0 c k ps1 (CC.TOther VIS) -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  env_agree GT.NF E0 E' -> L5.bytes_at RSEGS M' p ww -> WMATCH.
Proof.
  intros c k ps1 E' R' M1 M' IL HLF Hag HB.
  pose proof (CH2.leaves_all_sound _ _ _ wlit_ok _ _ _ _ _ IL) as Q. unfold wlit_chk in Q. cbv beta zeta iota in Q. rewrite Z.eqb_refl in Q.
  apply andb_prop in Q as (QR & QM).
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HKN.
  destruct (FRZW E' Hag) as (Hseg & Hwlen & _ & _).
  pose proof (SPW.rng_in_sound E' M' _ _ _ _ HKN QR) as HR.
  destruct WWF as (_ & Hlen & Hby).
  assert (HL : (NLITN <= length ww)%nat).
  { unfold NLITN, TAILB. cbn [length]. unfold NLIT in HR. unfold wlen in Hwlen. lia. }
  split; [exact HL|].
  unfold NLITN in *. apply SPTW.lit_cmp_true; [exact HL|].
  apply (SPTW.wmatch_sound SEG (SR.ps_cells ps1) (SPTW.litb_of TAILB) E' M' p ww QM HKN Hseg HB Hby).
  intros kl Hkl. unfold SPTW.litb_of, TAILB in Hkl. cbn in Hkl. unfold TAILB in HL. cbn [length] in HL.
  repeat (destruct Hkl as [<-|Hkl]; [cbn [fst]; lia|]). destruct Hkl.
Qed.
Lemma ww_leaf : forall g1 M0c, OKV M0c -> forall c ps1 Ec (M1 : mem) model1 E' R' (M' : mem), nth_error G.CPS 0 = Some c ->
  HAMBV g1 M0c 0 Ec M1 model1 -> env_agree GT.NF E0 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> L5.bytes_at RSEGS M' p ww.
Proof.
  intros g1 M0c OKV0 c ps1 Ec M1 model1 E' R' M' Hc HAmb AG HLF.
  pose proof (ww_at g1 M0c 0 Ec M1 model1 OKV0 HAmb) as HB1.
  pose proof (below_frame 0 c E' M1 M' Hc AG (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
  destruct WWF as (_ & Hlen & _). destruct WRNG as (Wp & We & _).
  pose proof STKF as (_ & S1 & S2' & S3 & S4). pose proof SCRP.
  apply (L5C.bytes_at_agree RSEGS M1 M' p ww); [| lia | lia | exact HB1].
  intros q Hq. apply FB. lia.
Qed.
Lemma vis_site : WMATCH -> forall g1 M0c c k ps1 cj ci, OKV M0c -> is_leaf 0 c k ps1 (CC.TOther VIS) ->
  forall Ec R1 (M1 : mem) model1 E' R' (M' : mem) cr1, CC.At (hl_segs L) c Ec R1 M1 -> HAMBV g1 M0c 0 Ec M1 model1 -> XIv g1 0 Ec M1 -> env_agree (CC.cp_nx c) Ec E' ->
    CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo eghost VBX.gB g1) sp G.HDECL W G.BLS (CredV g1) VBX.VIS_SCR 0 c ps1 cj ci 0 Ec E' R' M' model1 ->
    hi_heap HI ((CH2.den E' (nth 0 G.BLS []) ++ LBo) ++ g_lbv g1) cr1 M' (m_vmmaps model1) -> CredV g1 0 Ec cr1 ->
    True /\ enc_inv M' V S2 g1 /\ ev_guard (g_es g1) (EvNull) /\ eroomU g1 (EvNull) /\ PML.img_ro M' /\ PML.lits_ok M' /\
    PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps).
Proof.
  intros HWM g1 M0c c k ps1 cj ci OKV0 IL Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HX Hag HLF CF HH1 HC.
  pose proof IL as (tags & Hc & _).
  pose proof CF as [_ _ _ _ _ _ _ _ _ HagE' _ _].
  pose proof (gblocks_amb g1 M0c 0 Ec M1 model1 HAmb) as GB.
  pose proof (xinv_leaf g1 0 c Ec M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV' & HLIT').
  destruct HX as ((HX0 & _) & _ & HGF). cbn [Nat.leb] in HX0. unfold GF in HGF. cbn [Nat.eqb] in HGF. subst g1.
  destruct HX0 as (HF0 & _).
  split; [exact I|].
  split; [exact HINV'|].
  split; [exact I|].
  split; [exact (SPXWU.room_lit PMW.FParseNull TAILB PMR.ST_N cw ww eg (EvNull) eq_refl (proj1 HWM) (proj2 HWM) HROOM (or_introl eq_refl))|].
  split.
  { assert (HLS1 : PML.ls_ok g M1) by exact (PB2.ls_ok_keep M M1 HF0 g HG HLS).
    pose proof (below_frame 0 c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
    assert (HLS' : PML.ls_ok g M') by exact (PB2.ls_ok_keep M1 M' (fun a Ha => FB a (foot_low a Ha)) g HG HLS1).
    destruct HLS' as (HIMG & _). exact HIMG. }
  split; [exact HLIT'|].
  unfold CredV in HC. rewrite PMX.kenc_eq in HC.
  pose proof WFM as (_ & _ & _ & _ & HS4 & _). unfold scap in HS4. cbn [In] in HS4.
  exact (SPXWU.ecredit_of_pxU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr1 ps eg kx bxu HC Hkx Hbxu0 ltac:(lia)).
Qed.
Lemma vis_ret : WMATCH -> forall g1 c ps1 ci, nth_error G.CPS 0 = Some c ->
  forall Ec E' R' (M1 M' : mem) E2 (M2 : mem) g' cr', XIv g1 0 Ec M1 -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) Ec E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    env_agree (CH2.ci_nx ci) E' E2 -> (CC.cp_nx c <= CH2.ci_nx ci)%nat ->
    L5C.hpres L (CH2.den E' (nth 0 G.BLS []) ++ LBo) (sp + CH2.ci_csp ci) VBX.VIS_SCR (W_enc V S2) M' M2 ->
    hl_sptop L - 2 ^ 23 + VBX.VIS_SCR <= sp + CH2.ci_csp ci -> sp + CH2.ci_csp ci <= sp ->
    VBXU.vret V S2 g1 (EvNull) Ec g' M2 -> PMES.ecreditU L cr' g' (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps) ->
    XIv g' 1 E2 M2 /\ CredV g' 1 E2 cr'.
Proof.
  intros HWM g1 c ps1 ci Hc Ec E' R' M1 M' E2 M2 g' cr' HX HagE' Hag HLF Hag2 Hnx HP _ _ HR HCR.
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof OBJS as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OS1 & OS2 & _) & (OE1 & OE2 & _) & _).
  destruct HX as ((HX0 & _) & _ & HGF). cbn [Nat.leb] in HX0. unfold GF in HGF. cbn [Nat.eqb] in HGF. subst g1.
  destruct HR as (HINV2 & HLIT2 & Hes & Hpay).
  assert (HCV : CredV g' 1 E2 cr').
  { unfold CredV. rewrite PMX.kenc_eq.
    apply (SPXWU.px_of_ecreditU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr cr' ps eg g' kx bxu); [| exact Hkx | exact Hbxu0 | exact HCR].
    rewrite <- PMX.kenc_eq, <- Hbxu. exact HPC. }
  split; [|exact HCV].
  unfold XIv, WSIM, GF. cbn [Nat.leb Nat.eqb].
  split; [split; [|exact HWM] | split; [exact (conj HINV2 HLIT2) | split; [exact Hes | exact Hpay]]].
  pose proof (below_frame 0 c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
  destruct HX0 as (HF0 & HB0).
  assert (HF' : forall a, PB2.ls_foot a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) by (intros a Ha; rewrite (FB a (foot_low a Ha)); exact (HF0 a Ha)).
  pose proof (stack_below M1 M' FB HB0) as HB'.
  assert (SL2 : slen <= scap).
  { pose proof HPA as HPA'. unfold PML.parser_at in HPA'. do 29 (destruct HPA' as [_ HPA']). destruct HPA' as [SL _]. exact SL. }
  assert (SL1 : 1 <= slen).
  { pose proof WFM as (_ & _ & _ & _ & _ & C & HCs & _). unfold slen. rewrite HCs. cbn [length]. lia. }
  destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & _).
  destruct (Hwf (sb, scap)) as ((B0 & B1 & B2 & B3 & B4) & _); [apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto|].
  cbn [fst snd] in B0, B1, B2, B3, B4. rewrite ILO, IHI in B1.
  assert (HBLS : CH2.blocks_eqb (nth 0 G.BLS []) SPT.BL0 = true) by (vm_compute; reflexivity).
  assert (Hden : CH2.den E' (nth 0 G.BLS []) = PML.ps_blocks ps).
  { rewrite (CH2.blocks_eqb_eq _ _ HBLS). exact (kit SPT.den_BL0 E' HagE'). }
  unfold slen in SL1, SL2.
  split.
  + intros a Ha. rewrite <- (HF' a Ha). apply (L5C.hpres_kept _ _ _ _ _ _ _ a HP).
    pose proof (foot_low a Ha) as Fa.
    split; [lia|]. split; [|split].
    * right. right. rewrite ILO, IHI. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. split; [lia|]. intros X. pose proof (PmLayout.ly_static L LAY a X). lia.
    * unfold in_errno. rewrite LER. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. lia.
    * intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH in *; lia.
  + apply (L5C.bytes_at_agree RSEGS M' M2 sb (PML.ps_stack ps)); [| lia | lia | exact HB'].
    intros q Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
    split; [lia|]. split; [|split].
    * left. exists (sb, scap). split; [rewrite Hden; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; lia].
    * unfold in_errno. rewrite LER. lia.
    * intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia.
Qed.
Lemma leaf_vis : forall g1 M0c, OKV M0c -> forall c k ps1 cj ci, is_leaf 0 c k ps1 (CC.TOther VIS) -> CH2.ret_of G.RETS 0 k = Some 1%nat -> nth_error G.CPS 1 = Some cj -> SR.ps_pc ps1 = VIS ->
  VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth 0 G.BLS []) (nth 1 G.BLS []) = Some ci ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c 0 c ps1.
Proof.
  intros g1 M0c OKV0 c k ps1 cj ci IL Hret Hcj Hpc Hchk.
  intros fx' Ec R1 M1 model1 E' R' M' HAt HA HFP Hag HLF HIH.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (amb_agree g1 M0c 0 Ec M1 model1 (proj1 HA)) as A01.
  assert (NFc : (GT.NF <= CC.cp_nx c)%nat).
  { assert (Hcn : c = nth 0 G.CPS G.cp0) by (symmetry; apply nth_error_nth; exact Hc). rewrite Hcn. apply Nat.leb_le. vm_compute. reflexivity. }
  assert (AG : env_agree GT.NF E0 E') by (apply (CC.env_agree_trans _ E0 Ec E' A01); exact (CC.env_agree_le _ _ _ _ Hag NFc)).
  assert (HWM : WMATCH) by exact (wmatch_vis c k ps1 E' R' M1 M' IL HLF AG (ww_leaf g1 M0c OKV0 c ps1 Ec M1 model1 E' R' M' Hc (proj1 HA) AG HLF)).
  pose proof (kit SPT.UU) as (_ & _ & _ & UV).
  pose proof OBJS as (_ & OV' & OS' & _ & _ & _ & _ & AVS & _).
  exact (VBXU.vis_leaf_okU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
           G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) UV S2LT (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
           VIS (EvNull) _ (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
           0 c k ps1 1 cj ci g1 M0c (VNULL) (conj OV' (conj OS' AVS)) OKV0 IL Hret Hcj Hpc Hchk
           (vis_site HWM g1 M0c c k ps1 cj ci OKV0 IL) (vis_ret HWM g1 c ps1 ci Hc)
           fx' Ec R1 M1 model1 E' R' M' HAt HA HFP Hag HLF HIH).
Qed.

