(* [comment removed for export] *)
Lemma main : srealizes RSEGS SCFG (@PML.cfg fx R PCF M model) K.
Proof.
  unfold PML.cfg. change PCF with (CC.cp_pc G.cp0). rewrite <- LS.
  eapply (CH2V.cert_sound3V L HI HIok (PB.LYI_ L LAY) (PB.LYE_ L LAY) (PmLayout.ly_ro L LAY) GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv STKF SCRP NF32 U2 W_OK WRS_OK
            G.CPS K PML.fp_ok G.TAGS) with (i := 0%nat) (E := E0).
  - rewrite LS. exact FPM.
  - rewrite LS. exact G.plans.
  - exact G.tags_ok.
  - exact heap_ok3.
  - intros g1 i c k ps1 j s IL. exfalso. pose proof (CH2.leaves_all_sound _ _ _ leaf_ok _ _ _ _ _ IL) as Q. unfold leaf_chk in Q. cbv beta zeta iota in Q. repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in Q. discriminate Q.
  - intros g1 M0c OKV0 i c k ps1 j s IL. exfalso. pose proof (CH2.leaves_all_sound _ _ _ leaf_ok _ _ _ _ _ IL) as Q. unfold leaf_chk in Q. cbv beta zeta iota in Q. repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in Q. discriminate Q.
  - intros i c k ps1 pc IL g1 M0c OKV0. exact (leaves g1 M0c OKV0 i c k ps1 pc IL).
  - reflexivity.
  - rewrite LS. exact At0.
  - assert (Hden0 : CH2.den E0 (nth 0 G.BLS []) = PML.ps_blocks ps) by exact (kit SPT.den_BL0 E0 (CC.env_agree_refl _ _)).
    apply (CH2V.amb3V_intro L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv eg M 0%nat E0 M model (CH2V.okV_refl L M LBo sp G.HDECL W DEF0)).
    split.
    + split; [exact Hmo|]. split; [apply L5C.model_but_vm_refl|]. split; [apply CC.env_agree_refl|].
      split; [|split; [reflexivity | intros a _ _ Hd; exact Hd]].
      exists cr. split; [unfold CH2.cur, CH2V.LBr; rewrite Hden0; exact HH|].
      unfold CredV. rewrite <- Hbxu. exact HPC.
    + unfold XIv, XI0, WSIM, GF. cbn [Nat.leb Nat.eqb].
      split; [split; [split; [intros a _; reflexivity | exact (SPT.pa_stack M P ps HPA)] | exact I]|].
      split; [exact (conj HINV HLIT) | reflexivity].
  - exact Hfp.
Qed.
End Main.

(* [comment removed for export] *)
Section Final.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis SETEC_OK : PMS.set_ec_spec L.
Hypothesis VNULL : PMES.visit_null_specU L HI PMES.WD_SCR_X.

(* [comment removed for export] *)
Theorem parse_null_okw : PMW.parse_null_specwU L HI PML.STRTOD_SCR_V PMES.WD_SCR_X PMR.the_rm.
Proof.
  unfold PMW.parse_null_specwU, PMW.ptransxwU, PMW.ptrans_gxwU, PMW.ptrans_gbxwU.
  intros LBo cr sp r P V E S2 B kx bx g ps eg w x c. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & ((Ha0 & Ha1 & Ha2) & Hmore & Hnex & Hexp) & HPA & HWF & HWIN & HBB & HVIS & HEC & HLS & HG & HINV & HLIT & HSYNC & Hkx & Hbx & HPC & OBJS & HWBY & HRM & HROOM) Hcont.
  assert (Hpe : exists p e, PML.ps_win ps = Some (p, e)).
  { revert Hnex. unfold PMS.win_exhausted. destruct (PML.ps_win ps) as [[p e]|]; intros Hnex; [eauto | exfalso; exact (Hnex I)]. }
  destruct Hpe as (p & e & Hwin).
  pose proof (SPT.pa_def _ _ _ HPA) as HdP.
  destruct (PB2.cell_exists M (P + 160) 8 ltac:(lia)) as (line0 & Rl & Hl); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  destruct (PB2.cell_exists M (P + 168) 8 ltac:(lia)) as (pos0 & Rp & Hp); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  pose proof HWBY as HWB'. unfold PMW.win_bytes in HWB'. rewrite Hwin in HWB'. destruct HWB' as (Hwb1 & Hwb2 & _).
  eapply main with (kx := kx) (bx := bx + PMES.benc L eg) (bxu := bx).
  all: first [ exact Hcont | exact (conj Rl Rp) | exact (conj Hwb1 Hwb2) | eassumption | reflexivity ].
Qed.
